style.css:
div:nth-child(6) > div:nth-child(1) {
  z-index: -1;
  background-color: rgb(0, 0, 0);
  position: fixed;
  inset: 0px;
  box-sizing: border-box;
  margin: 0px;
  padding: 0px;
}
nav {
  pointer-events: all;
  background-color: rgb(45, 42, 42);
  border-bottom: 1px solid rgb(255, 0, 0);
  width: 100%;
  position: fixed;
  z-index: 1100;
  height: var(--header-height);
  left: 0px;
  --bs-navbar-padding-x:0;
  --bs-navbar-padding-y:.5rem;
  --bs-navbar-color:rgba(0,0,0,.65);
  --bs-navbar-hover-color:rgba(0,0,0,.8);
  --bs-navbar-disabled-color:rgba(0,0,0,.3);
  --bs-navbar-active-color:rgba(0,0,0,1);
  --bs-navbar-brand-padding-y:.3125rem;
  --bs-navbar-brand-margin-end:1rem;
  --bs-navbar-brand-font-size:1.25rem;
  --bs-navbar-brand-color:rgba(0,0,0,1);
  --bs-navbar-brand-hover-color:rgba(0,0,0,1);
  --bs-navbar-nav-link-padding-x:.5rem;
  --bs-navbar-toggler-padding-y:.25rem;
  --bs-navbar-toggler-padding-x:.75rem;
  --bs-navbar-toggler-font-size:1.25rem;
  --bs-navbar-toggler-icon-bg:url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%2833, 37, 41, 0.75%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
  --bs-navbar-toggler-border-color:rgba(0,0,0,.15);
  --bs-navbar-toggler-border-radius:.375rem;
  --bs-navbar-toggler-focus-width:.25rem;
  --bs-navbar-toggler-transition:box-shadow .15s ease-in-out;
  padding: var(--bs-navbar-padding-y)var(--bs-navbar-padding-x);
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  display: flex;
  box-sizing: border-box;
  margin: 0px;
}
